585	     1	import { db } from "@/lib/db";
586	     2	import { requireUser } from "@/lib/auth";
587	     3	import { AutoRefresh } from "@/components/AutoRefresh";
588	     4	import { PageHeader } from "@/components/ui/primitives";
589	     5	import {
590	     6	  SslCertificates,
591	     7	  type CertRow,
592	     8	  type QueueInfo,
593	     9	  type ServerOption,
594	    10	} from "@/components/customer/SslCertificates";
595	    11	
596	    12	export const dynamic = "force-dynamic";
597	    13	
598	    14	type SslPayload = { certId?: string; domain?: string; renewal?: boolean };
599	    15	
600	    16	export default async function SslPage() {
601	    17	  const user = await requireUser();
602	    18	
603	    19	  const [certificates, servers] = await Promise.all([
604	    20	    db.sslCertificate.findMany({
605	    21	      where: { userId: user.id },
606	    22	      orderBy: { createdAt: "desc" },
607	    23	    }),
608	    24	    db.server.findMany({
609	    25	      where: { userId: user.id },
610	    26	      orderBy: { createdAt: "desc" },
611	    27	    }),
612	    28	  ]);
613	    29	
614	    30	  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
615	    31	  const myServerIds = new Set(servers.map((s) => s.id));
616	    32	
617	    33	  // ---------------------------------------------------------------------------
618	    34	  // Queue visibility.
619	    35	  //
620	    36	  // The worker claims ONE job at a time platform-wide — `worker/index.ts` picks
621	    37	  // the oldest `status: "QUEUED"` row and awaits it inside a serial `for(;;)` —
622	    38	  // so a certificate request genuinely can sit behind another tenant's long
623	    39	  // MIGRATE. That happened on 2026-07-26: a request read "pending" for 13
624	    40	  // minutes with nothing on screen to distinguish a queue from a crash, so the
625	    41	  // customer had no way to know whether to wait or retry. Resolve the real
626	    42	  // position here (this page already polls) instead of leaving them guessing.
627	    43	  // ---------------------------------------------------------------------------
628	    44	  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
629	    45	  const queueByCert = new Map<string, QueueInfo>();
630	    46	
631	    47	  if (inflight.length > 0) {
632	    48	    const [sslJobs, running] = await Promise.all([
633	    49	      db.job.findMany({
634	    50	        where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
635	    51	        select: { id: true, status: true, createdAt: true, payload: true },
636	    52	        orderBy: { createdAt: "asc" },
637	    53	      }),
638	    54	      // Whatever is holding the single worker slot right now.
639	    55	      db.job.findFirst({
640	    56	        where: { status: "RUNNING" },
641	    57	        select: { type: true, serverId: true },
642	    58	        orderBy: { createdAt: "asc" },
643	    59	      }),
644	    60	    ]);
645	    61	
646	    62	    for (const cert of inflight) {
647	    63	      const job = sslJobs.find((j) => ((j.payload ?? {}) as SslPayload).certId === cert.id);
648	    64	
649	    65	      // No queued or running job at all: the request cannot make progress. Say so
650	    66	      // rather than spinning — the reconcile sweep will age it out, and the row is
651	    67	      // deletable in the meantime.
652	    68	      if (!job) {
653	    69	        queueByCert.set(cert.id, {
654	    70	          state: "none",
655	    71	          position: 0,
656	    72	          aheadCount: 0,
657	    73	          queuedAtIso: cert.createdAt.toISOString(),
658	    74	          blocking: null,
659	    75	        });
660	    76	        continue;
661	    77	      }
662	    78	
663	    79	      if (job.status === "RUNNING") {
664	    80	        queueByCert.set(cert.id, {
665	    81	          state: "running",
666	    82	          position: 0,
667	    83	          aheadCount: 0,
668	    84	          queuedAtIso: job.createdAt.toISOString(),
669	    85	          blocking: null,
670	    86	        });
671	    87	        continue;
672	    88	      }
673	    89	
674	    90	      // FIFO by createdAt, matching the worker's claim order exactly.
675	    91	      const aheadCount = await db.job.count({
676	    92	        where: { status: "QUEUED", createdAt: { lt: job.createdAt } },
677	    93	      });
678	    94	      queueByCert.set(cert.id, {
679	    95	        state: "queued",
680	    96	        position: aheadCount + 1,
681	    97	        aheadCount,
682	    98	        queuedAtIso: job.createdAt.toISOString(),
683	    99	        blocking: running
684	   100	          ? {
685	   101	              type: running.type,
686	   102	              // Only the job type is exposed, never whose server it is beyond
687	   103	              // "yours or not" — enough to explain the wait, nothing more.
688	   104	              mine: running.serverId ? myServerIds.has(running.serverId) : false,
689	   105	            }
690	   106	          : null,
691	   107	      });
692	   108	    }
693	   109	  }
694	   110	
695	   111	  const rows: CertRow[] = certificates.map((c) => ({
696	   112	    id: c.id,
697	   113	    domain: c.domain,
698	   114	    status: c.status,
699	   115	    issuer: c.issuer,
700	   116	    autoRenew: c.autoRenew,
701	   117	    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
702	   118	    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
703	   119	    // The observed notAfter, or null. Nothing here is ever a computed guess.
704	   120	    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
705	   121	    lastError: c.lastError,
706	   122	    queue: queueByCert.get(c.id) ?? null,
707	   123	  }));
708	   124	
709	   125	  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
710	   126	  const serverOptions: ServerOption[] = servers
711	   127	    .filter((s) => s.status === "RUNNING")
712	   128	    .map((s) => ({ id: s.id, hostname: s.hostname }));
713	   129	
714	   130	  const transitional = inflight.length > 0;
715	   131	
716	   132	  return (
717	   133	    <div className="space-y-6">
718	   134	      {transitional && <AutoRefresh />}
719	   135	      <PageHeader
720	   136	        title="SSL Certificates"
721	   137	        sub="One-click Let's Encrypt certificates for domains pointed at your servers. Renewed automatically from 21 days before expiry."
722	   138	      />
723	   139	      <SslCertificates certificates={rows} servers={serverOptions} />
724	   140	    </div>
725	   141	  );
726	   142	}
